<script lang="ts">
 import { gymCommand, GYM_GUIDE } from '$lib/gym/commands';
 import CaseResult from './CaseResult.svelte';
 import type { ClimbSession, Evaluation } from '$lib/gym/session';
 let { run }: {run: ClimbSession} = $props();
 let stage = $state('final');
 let failuresOnly = $state(false);
 let copied = $state(false);
 let copyError = $state('');
 const round = $derived(run.rounds.find(r=>String(r.index)===stage));
 const before = $derived(stage === 'final' ? run.verification?.baseline : run.baseline);
 const after = $derived(stage === 'final' ? run.verification?.candidate : round?.candidate?.score ? round.candidate as Evaluation : null);
 const tests = $derived(run.suite.cases.filter(c=>before?.samples.some(s=>s.caseId===c.id) || after?.samples.some(s=>s.caseId===c.id)));
 const visibleTests = $derived(tests.filter(c=>!failuresOnly || [...before?.samples??[],...after?.samples??[]].some(s=>s.caseId===c.id&&!s.passed)));
 const labels = {verified:'Passed fresh verification','not-verified':'Failed fresh verification','no-defect':'Original skill kept','no-improvement':'No candidate selected',running:'Run in progress',error:'Run stopped',cancelled:'Run cancelled'};
 const command = $derived(gymCommand('climb',run.suite.id,run.runner.model,` --rounds ${run.config.maxRounds} --repetitions ${run.config.repetitions}`));
 const selected = $derived(run.selected ?? run.original);
 const repaired = $derived(run.strategy==='repair' && run.verification?.candidate ? run.verification : null);
 const reduction = $derived(Math.round((1-selected.words/run.original.words)*100));
 async function copy() { try { await navigator.clipboard.writeText(command); copied=true; copyError=''; setTimeout(()=>copied=false,1800); } catch { copyError='Select and copy the command below.'; } }
 function download(content: string, name: string, type: string) { const url=URL.createObjectURL(new Blob([content],{type})); const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000); }
 const count = (e: Evaluation | null | undefined, id: string) => { const c=e?.score.byCase[id];return c?`${c.passed}/${c.total}`:'—'; };
</script>

<article>
 <div class="topline"><span class="outcome" class:verified={run.status==='verified'}>{labels[run.status]}</span><span>{run.strategy==='ablate'?'Shorten':'Repair'} · {run.runner.model}</span></div>
 <h2>{run.suite.title ?? run.suite.skillName ?? run.suite.id}</h2>
 <p class="description">{run.suite.description ?? 'A local experiment with repeated trials.'}</p>
 {#if run.suite.seededDefect}<p class="notice">Controlled defect: {run.suite.seededDefect}</p>{/if}
 <div class="scoreboard">
  <div><span>{repaired ? 'Original · fresh trials' : 'Original'}</span><strong>{repaired ? `${repaired.baseline?.score.passed}/${repaired.baseline?.score.total}` : run.original.words}<small>{repaired ? ' passed' : ' words'}</small></strong></div>
  <span class="direction" aria-hidden="true">→</span>
  <div><span>{repaired ? 'Selected · fresh trials' : 'Selected in training'}</span><strong>{repaired ? `${repaired.candidate?.score.passed}/${repaired.candidate?.score.total}` : selected.words}<small>{repaired ? ' passed' : ' words'}</small></strong></div>
  <div class="change"><strong>{selected.hash===run.original.hash?'Unchanged':reduction>0?`−${reduction}%`:reduction<0?`+${-reduction}%`:'Same length'}</strong><span>{selected.hash===run.original.hash?'No edit selected':reduction>0?'less skill text':reduction<0?'more skill text':'Skill text revised'}</span></div>
 </div>
 {#if run.verification?.decision}<p class="decision">{run.status==='verified' && run.verification.baseline && run.verification.candidate ? `Fresh trials: original ${run.verification.baseline.score.passed}/${run.verification.baseline.score.total}; selected ${run.verification.candidate.score.passed}/${run.verification.candidate.score.total}. ${run.strategy==='ablate'?'The shorter version passed every check.':'The repair passed every check.'}` : run.verification.decision.reason}</p>{:else}<p class="decision">{run.stopReason ?? 'The search kept the original skill.'} {run.verification?.baseline && run.verification.baseline.score.rate<1 ? 'The original failed a held-out trial. The gym did not use that result to make another edit.' : ''}</p>{/if}
 {#if run.error}<p class="notice" role="alert">{run.error}</p>{/if}

 <section class="rounds" aria-labelledby="rounds-heading">
  <div class="section-head"><h3 id="rounds-heading">The search</h3><span>Training cases only</span></div>
  <div class="round-heading" aria-hidden="true"><span>Version</span><span>Words</span><span>Passed trials</span><span>Decision</span></div>
  <div class="round-row original"><strong>Original</strong><span>{run.original.words}</span><span>{run.baseline?.score.passed ?? '—'} / {run.baseline?.score.total ?? '—'}</span><span>Starting point</span></div>
  {#each run.rounds as r}
   <button class="round-row" class:active={stage===String(r.index)} disabled={!r.candidate?.score} onclick={()=>{stage=String(r.index);failuresOnly=false;}} aria-pressed={stage===String(r.index)} aria-label={`Inspect round ${r.index}, ${r.status}`}><strong><span class="round-number">{r.index}</span> Round {r.index}</strong><span>{r.candidate?.words ?? '—'}</span><span>{r.candidate?.score?.passed ?? '—'} / {r.candidate?.score?.total ?? '—'}</span><span class:kept={r.status==='accepted'}>{r.status==='accepted'?'Keep':r.status==='rejected'?'Reject':r.status}</span></button>
  {/each}
  {#if !run.rounds.length}<p class="no-rounds">All training trials passed. There was no training failure to repair.</p>{/if}
  <button class="final-row" class:active={stage==='final'} onclick={()=>{stage='final';failuresOnly=false;}} aria-pressed={stage==='final'}><span><strong>{run.verification?.candidate?'Fresh verification':'Held-out check'}</strong><small>{run.verification?.candidate?'New responses. Selected skill locked before this check.':'Original skill. Cases kept out of the search.'}</small></span><span>{run.verification?.candidate ? `${run.verification.candidate.score.passed} / ${run.verification.candidate.score.total}` : run.verification?.baseline ? `${run.verification.baseline.score.passed} / ${run.verification.baseline.score.total}` : 'Pending'}<small>passed trials</small></span></button>
 </section>

 <section class="evidence" aria-labelledby="evidence-heading">
  <div class="section-head"><h3 id="evidence-heading">{stage==='final'?'Verification evidence':`Round ${stage} evidence`}</h3><label><input type="checkbox" bind:checked={failuresOnly} /> Failures only</label></div>
  {#if round}<p class="explanation">{round.candidate?.rationale} {round.decision?.reason}</p>{/if}
  <p class="explanation">{stage==='final'?'These results did not guide the edits.':'Compare this candidate with the original training run.'} Each row contains {run.config.repetitions} trials. A trial passes only if every check passes.</p>
  <div class="evidence-head"><span>Test case</span><span>Original</span><span>{after?'Candidate':'—'}</span></div>
  {#each visibleTests as test}
   <details class="test-group"><summary><span>{test.title}<small>{test.split==='holdout'?'Held out of search':'Training case'}</small></span><strong>{count(before,test.id)}</strong><strong>{count(after,test.id)}</strong></summary><div class="attempts">{#each Array.from({length:run.config.repetitions},(_,i)=>i+1) as repetition}<CaseResult test={{...test,title:`Trial ${repetition}`}} before={before?.samples.find(s=>s.caseId===test.id&&s.repetition===repetition)} after={after?.samples.find(s=>s.caseId===test.id&&s.repetition===repetition)} hasCandidate={!!after} />{/each}</div></details>
  {/each}
  {#if !visibleTests.length}<p class="no-rounds">{failuresOnly?'No failed trials in this view.':'No completed evidence yet.'}</p>{/if}
 </section>

 <details class="skill-source"><summary>Read the original and selected skill <span>{run.original.words} → {selected.words} words</span></summary><div class="source-grid">{#each [{label:'Original',v:run.original},{label:'Selected in training',v:selected}] as item}<section><h4>{item.label}</h4><small>sha256 · {item.v.hash.slice(0,12)}</small><!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable source needs keyboard access.) --><pre tabindex="0" role="region" aria-label={`${item.label} skill source`}>{item.v.content}</pre></section>{/each}</div></details>
 <div class="reproduce"><div><h3>Run your own experiment</h3><p>Use the available GitHub build with Node 22+ and a signed-in Codex CLI.</p></div><button onclick={copy}>{copied?'Copied':'Copy command'}</button><code>{command}</code><p class="release-note">The short npm command needs Loooom 0.3.0, which is not published yet. This command uses the saved source version. <a href={GYM_GUIDE}>Source setup guide</a>.</p>{#if copyError}<p role="status">{copyError}</p>{/if}</div>
 <div class="downloads"><button onclick={()=>download(JSON.stringify(run,null,2),`${run.id}.json`,'application/json')}>Download all evidence ↓</button><button onclick={()=>download(selected.content,`${run.suite.skillName??run.suite.id}-candidate.md`,'text/markdown')}>Download selected skill ↓</button></div>
 <p class="limitation">{run.limitation}</p>
 <div class="provenance"><span>{run.calls} model calls · {run.config.maxRounds} round limit</span>{#if run.suite.sourceUrl}<a href={run.suite.sourceUrl} target="_blank" rel="noreferrer">Original skill ↗</a>{/if}<span>Suite {run.suiteHash.slice(0,12)} · {new Date(run.startedAt).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'})}</span></div>
</article>

<style>
 .topline,.section-head,.downloads,.provenance { display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap; }.topline {font-size:.8rem;color:var(--text-secondary)}.outcome {border:1px solid var(--border);padding:8px 12px;border-radius:var(--radius-sm);color:var(--text-primary)}.outcome.verified{background:var(--accent-glow);border-color:var(--accent);color:var(--accent)}
 h2{font-size:clamp(1.8rem,3vw,2.5rem);line-height:1.16;font-weight:500;margin:22px 0 12px}.description,.explanation,.limitation {color:var(--text-secondary);line-height:1.7}.description {max-width:66ch}.scoreboard{display:flex;align-items:center;gap:28px;margin:30px 0 16px;padding:26px 0;border-block:1px solid var(--border)}.scoreboard>div{display:flex;flex-direction:column;gap:10px}.scoreboard span{font-size:.8rem;color:var(--text-secondary)}.scoreboard strong{font-size:2.5rem;font-weight:500;line-height:1.15;font-variant-numeric:tabular-nums}.scoreboard strong small{font-size:.85rem;color:var(--text-secondary);font-weight:400}.scoreboard .direction{font-size:1.5rem}.scoreboard .change{margin-left:auto}.change strong{color:var(--accent);font-size:1.6rem}.decision{font-size:.95rem;line-height:1.7}.notice{padding:16px;background:var(--bg-secondary);border-left:1px solid var(--rose);margin-top:18px;line-height:1.6}
 .rounds,.evidence{margin-top:36px}h3{font-size:1.1rem;font-weight:500}.section-head{margin-bottom:18px}.section-head>span,.section-head label{font-size:.8rem;color:var(--text-secondary)}.section-head label{display:flex;align-items:center;gap:8px;cursor:pointer}input{accent-color:var(--accent)}.round-heading,.round-row{display:grid;grid-template-columns:minmax(120px,1.2fr) .6fr .8fr 1fr;gap:16px;text-align:left;align-items:center}.round-heading{font-size:.7rem;color:var(--text-secondary);padding:0 14px 12px}.round-row{width:100%;background:transparent;border:0;border-top:1px solid var(--border);padding:18px 14px;font-family:inherit;font-size:.85rem;color:var(--text-primary);font-variant-numeric:tabular-nums}.round-row strong{font-weight:500}.round-row:not(.original){cursor:pointer}.round-row.active{background:var(--bg-secondary)}.round-row:hover:not(.original){background:var(--accent-glow)}.round-number{display:none}.round-row .kept{color:var(--accent);font-weight:600}.round-row.original{color:var(--text-secondary)}.final-row{width:100%;display:flex;justify-content:space-between;align-items:center;gap:24px;padding:20px 14px;margin-top:8px;border:1px solid var(--border);border-left:1px solid var(--border);background:transparent;text-align:left;color:var(--text-primary);font-family:inherit;cursor:pointer}.final-row.active{border-left-color:var(--accent);background:var(--bg-card)}.final-row strong{font-weight:500}.final-row small{display:block;font-size:.75rem;color:var(--text-secondary);line-height:1.5;margin-top:6px}.final-row>span:last-child{flex-shrink:0;font-variant-numeric:tabular-nums}.no-rounds{padding:22px 0;color:var(--text-secondary);font-size:.9rem;line-height:1.6}.explanation{font-size:.85rem;margin-bottom:18px}.evidence-head,.test-group>summary{display:grid;grid-template-columns:minmax(0,1fr) 80px 80px;gap:18px}.evidence-head{font-size:.7rem;color:var(--text-secondary);padding:16px 0;border-bottom:1px solid var(--border)}.test-group>summary{padding:22px 0;cursor:pointer;list-style:none;align-items:center;border-bottom:1px solid var(--border)}.test-group>summary::-webkit-details-marker{display:none}.test-group>summary>span{font-weight:500;line-height:1.4}.test-group>summary>span::before{content:'+';display:inline-block;width:18px;color:var(--accent)}.test-group[open]>summary>span::before{content:'−'}.test-group small{display:block;font-size:.75rem;color:var(--text-secondary);font-weight:400;margin-top:6px}.test-group strong{font-size:.95rem;color:var(--accent);font-variant-numeric:tabular-nums}.attempts{padding:0 16px;background:var(--bg-card)}
 .skill-source{margin-top:32px;border-block:1px solid var(--border)}.skill-source>summary{padding:22px 0;cursor:pointer;line-height:1.6}.skill-source>summary>span{font-size:.8rem;color:var(--text-secondary);margin-left:12px}.source-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;padding-bottom:24px}.source-grid section{min-width:0}.source-grid h4{font-size:.9rem;font-weight:500}.source-grid small{display:block;margin:8px 0 14px;font-family:var(--font-mono);font-size:.65rem;color:var(--text-secondary)}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.8rem;line-height:1.7;background:var(--bg-secondary);padding:18px;max-height:420px;overflow:auto}.reproduce{margin-top:32px;display:grid;grid-template-columns:1fr auto;gap:18px;align-items:center}.reproduce p{margin-top:10px;font-size:.85rem;color:var(--text-secondary);line-height:1.6}.reproduce code{grid-column:1/-1;background:var(--bg-secondary);padding:18px;font-size:.8rem;line-height:1.8;overflow-wrap:anywhere}.reproduce .release-note{grid-column:1/-1;margin-top:0}.reproduce button{border:1px solid var(--accent);color:var(--accent);background:transparent;padding:12px 16px;border-radius:var(--radius-sm);font:inherit;font-size:.8rem;cursor:pointer}.downloads{justify-content:flex-start;margin-top:22px}.downloads button{font:inherit;color:var(--accent);font-size:.85rem;background:none;border:0;border-bottom:1px solid var(--border);padding:8px 0;cursor:pointer}.limitation{font-size:.8rem;margin-top:28px}.provenance{font-size:.7rem;color:var(--text-secondary);justify-content:flex-start;margin-top:18px;line-height:1.6}a{color:var(--accent);text-underline-offset:4px}button:focus-visible,summary:focus-visible,pre:focus-visible,a:focus-visible{outline:2px solid var(--accent);outline-offset:4px}
 @media(max-width:600px){.scoreboard{gap:14px;flex-wrap:wrap}.scoreboard strong{font-size:2rem}.scoreboard .change{width:100%;margin:6px 0 0;flex-direction:row;align-items:baseline;gap:12px}.change strong{font-size:1.4rem}.round-heading,.round-row{grid-template-columns:minmax(70px,1fr) 44px 72px 60px;gap:8px;padding-left:6px;padding-right:6px}.round-heading{font-size:.65rem}.round-row{font-size:.8rem}.final-row{gap:16px}.final-row small{font-size:.7rem}.evidence-head,.test-group>summary{grid-template-columns:minmax(0,1fr) 48px 55px;gap:10px}.evidence-head{font-size:.65rem}.test-group>summary>span{font-size:.9rem}.source-grid{grid-template-columns:1fr}.reproduce{grid-template-columns:1fr}.reproduce button{justify-self:start}.reproduce code{grid-column:auto}.attempts{padding:0 8px}}
</style>
